import { readFileSync } from "node:fs";

function fail(message) {
  console.error(message);
  process.exit(1);
}

let plan;
try {
  plan = JSON.parse(readFileSync("plan.json", "utf8"));
} catch {
  fail("plan.json is missing or not valid JSON");
}

if (typeof plan !== "object" || plan === null) fail("plan.json must be an object");
if (typeof plan.title !== "string" || plan.title.length < 1 || plan.title.length > 40) {
  fail("title must be a string of 1-40 characters");
}
if (typeof plan.hook !== "string" || plan.hook.length < 1 || plan.hook.length > 80) {
  fail("hook must be a string of 1-80 characters");
}
if (!Array.isArray(plan.outline) || plan.outline.length < 3 || plan.outline.length > 5) {
  fail("outline must have 3-5 items");
}
for (const item of plan.outline) {
  if (typeof item !== "string" || item.trim() === "") fail("outline items must be non-empty strings");
}
if (!Array.isArray(plan.hashtags) || plan.hashtags.length < 3 || plan.hashtags.length > 5) {
  fail("hashtags must have 3-5 items");
}
for (const tag of plan.hashtags) {
  if (typeof tag !== "string" || !/^#[^\s#]+$/.test(tag)) fail(`invalid hashtag: ${tag}`);
}
if (!JSON.stringify(plan).toLowerCase().includes("camping")) {
  fail('the keyword "camping" must appear in the plan');
}

console.log("self-media ok");
